import fs from 'fs';
import { checkpoint } from "@tigrisdata/agent-kit";

async function main() {
  const trialId = fs.readFileSync('/logs/artifacts/trial_id', 'utf-8').trim();
  const bucketName = `harbor-pipeline-${trialId}`.toLowerCase().replace(/[^a-z0-9.-]/g, '-');

  const buildId = fs.readFileSync('/home/user/ckpt-tag/build_id.txt', 'utf-8').trim();
  const unixTimestamp = Math.floor(Date.now() / 1000);

  const name = `release-${buildId}-${unixTimestamp}`;

  const { data: ckpt, error } = await checkpoint(bucketName, { name });
  if (error) {
    console.error("Checkpoint error:", error);
    process.exit(1);
  }

  const output = {
    snapshotId: ckpt.snapshotId,
    name: name
  };

  fs.writeFileSync('/home/user/ckpt-tag/snapshot.json', JSON.stringify(output, null, 2));
}

main().catch(err => {
  console.error("Fatal error:", err);
  process.exit(1);
});

import { S3Client, ListBucketsCommand } from "@aws-sdk/client-s3";

async function main() {
  const client = new S3Client({
    region: "REDACTED",
    endpoint: "https://fly.storage.tigris.dev",
    credentials: {
      accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
      secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!
    }
  });

  const { Buckets } = await client.send(new ListBucketsCommand({}));
  console.log(Buckets?.map(b => b.Name));
}
main();

