import { removeBucket, createBucket } from "@tigrisdata/storage";

async function main() {
  const bucketName = 'harbor-pipeline-timestamped-checkpoint-tagging--duzekkr';
  console.log("Removing bucket...");
  const { error: err1 } = await removeBucket(bucketName, { force: true });
  if (err1) {
    console.error("Remove error:", err1);
  } else {
    console.log("Bucket removed.");
  }

  console.log("Creating bucket with snapshots enabled...");
  const { data, error: err2 } = await createBucket(bucketName, { enableSnapshot: true });
  if (err2) {
    console.error("Create error:", err2);
  } else {
    console.log("Bucket created:", data);
  }
}
main();

import { createBucket } from "@tigrisdata/storage";

async function main() {
  const bucketName = 'harbor-pipeline-timestamped-checkpoint-tagging--duzekkr';
  let created = false;
  for (let i = 0; i < 30; i++) {
    const { data, error } = await createBucket(bucketName, { enableSnapshot: true });
    if (!error) {
      console.log("Bucket created:", data);
      created = true;
      break;
    }
    console.log("Attempt", i, "failed:", error.message);
    await new Promise(r => setTimeout(r, 2000));
  }
  if (!created) {
    console.error("Failed to recreate bucket");
  }
}
main();

